            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            top=min(y for y,x in comp); bottom=max(y for y,x in comp)
            left=min(x for y,x in comp); right=max(x for y,x in comp)
            if bottom-top < 2 or right-left < 2:
                continue
            boundary={(y,x) for y in range(top,bottom+1) for x in range(left,right+1)
                      if y in (top,bottom) or x in (left,right)}
            if boundary.issubset(set(comp)):
                area=(bottom-top-1)*(right-left-1)
                fill=7 if area % 2 else 2
                for y in range(top+1,bottom):
                    for x in range(left+1,right): out[y][x]=fill
    return out
